// Ordered by objectId for the /api/houses next-link chain
export const ORDERED_HOUSES = [...CSV_HOUSES].sort((a, b) => a.objectId - b.objectId);

export function getHouseById(id: string): CsvHouse | undefined {
  return CSV_HOUSES.find((h) => h.id === id);
}

export function getNextHouseId(id: string): string | null {
  const idx = ORDERED_HOUSES.findIndex((h) => h.id === id);
  if (idx === -1 || idx === ORDERED_HOUSES.length - 1) return null;
  return ORDERED_HOUSES[idx + 1].id;
}
